class Solution {
    public int findMin(int[] nums) {
        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] > nums[right]) {
                // mid在前半段（较大元素），最小值在右边
                left = mid + 1;
            } else {
                // mid在后半段（较小元素），最小值在左边或就是mid
                right = mid;
            }
        }

        return nums[left];
    }
}

