class Solution {
    public int jump(int[] nums) {
        int curEnd = 0;
        int nextEnd = 0;
        int steps = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            nextEnd = Math.max(nextEnd, i + nums[i]);
            if (i == curEnd) {
                steps++; // 扫完一层，才增加一步
                curEnd = nextEnd;
            }
        }
        return steps;
    }
}

